139	    /** Two owners share a household when they resolve to the same {@link Owner#getHouseholdId()}
140	     *  (matching last name and postcode). */
141	    private static boolean sameHousehold(Owner a, Owner b) {
142	        return a.getHouseholdId() != null && a.getHouseholdId().equals(b.getHouseholdId());
