16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	@EntityListeners(OwnerAuditListener.class)
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form, e.g. +61412345678")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "postcode")
56	    private String postcode;
57	
58	    @Column(name = "registration_date", columnDefinition = "DATE")
59	    private LocalDate registrationDate;
60	
61	    @Column(name = "birth_date", columnDefinition = "DATE")
62	    private LocalDate birthDate;
63	
64	    @Column(name = "customer_code")
65	    private String customerCode;
66	
67	    @Column(name = "namesake_count")
68	    private Integer namesakeCount;
69	
70	    @Column(name = "household_member_count")
71	    private Integer householdMemberCount;
72	
73	    @Column(name = "possible_duplicate")
74	    private Boolean possibleDuplicate;
75	
76	    @Column(name = "possible_duplicate_of")
77	    private Integer possibleDuplicateOf;
78	
79	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
80	    private Set<Pet> pets;
81	
82	    /** Default an absent registration date to the server's current date on first persist. */
83	    @PrePersist
84	    void defaultRegistrationDate() {
85	        if (this.registrationDate == null) {
86	            this.registrationDate = LocalDate.now();
87	        }
88	    }
89	
90	    public LocalDate getRegistrationDate() {
91	        return this.registrationDate;
92	    }
93	
94	    public void setRegistrationDate(LocalDate registrationDate) {
95	        this.registrationDate = registrationDate;
96	    }
97	
98	    public LocalDate getBirthDate() {
99	        return this.birthDate;
100	    }
101	
102	    public void setBirthDate(LocalDate birthDate) {
103	        this.birthDate = birthDate;
104	    }
105	
106	    public String getCustomerCode() {
107	        return this.customerCode;
108	    }
109	
110	    /** Stable identifier shared by owners of the same household (matching last name and postcode). */
111	    @Transient
112	    public String getHouseholdId() {
113	        return HouseholdId.of(getLastName(), this.postcode);
114	    }
115	
116	    public void setCustomerCode(String customerCode) {
117	        this.customerCode = customerCode;
118	    }
119	
